import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color, float } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root group
  const root = new Group();

  // Panel geometry
  const PANEL_W = 3.4;
  const PANEL_H = 1.9;
  const panelGeom = new PlaneGeometry(PANEL_W, PANEL_H);
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.transparent = true;
  panelMat.opacity = 0;
  panelMat.colorNode = mix(color('#1a1a22'), color('#111116'), uv().y);
  panelMat.roughnessNode = float(0.6);
  panelMat.metalnessNode = float(0.2);
  panelMat.clearcoatNode = float(0.1);
  const panelMesh = new Mesh(panelGeom, panelMat);
  root.add(panelMesh);

  // Text items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const left = -PANEL_W / 2;
  const top = PANEL_H / 2;
  const padding = 0.5; // base unit *2
  const quoteMarkHeight = 0.62;
  const quoteMarkDepth = 0.04;

  // Helper to create and position text
  const createAndPlace = (text, opts, pos, z = 0.03) => {
    const txt = ctx.fontAtlas.createText(text, opts);
    txt.position.set(pos.x, pos.y, z);
    root.add(txt);
    return txt;
  };

  // Quote mark (accent)
  const quoteMarkItem = items.find(i => i.role === 'quote-mark') || { text: '“' };
  const quoteMarkOpts = {
    fontSize: quoteMarkItem.typography?.fontSize || 62,
    color: '#ff2a38',
    align: 'left',
  };
  const qmX = left + padding + quoteMarkHeight / 2;
  const qmY = top - padding - quoteMarkHeight / 2;
  const quoteMarkObj = createAndPlace(quoteMarkItem.text, quoteMarkOpts, { x: qmX, y: qmY });

  // Quote text
  const quoteItem = items.find(i => i.role === 'quote') || { text: 'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.' };
  const quoteOpts = {
    fontSize: quoteItem.typography?.fontSize || 20,
    color: '#e8ecf2',
    align: 'left',
  };
  const quoteY = qmY - 0.25 - 0.2; // approximate line height
  const quoteObj = createAndPlace(quoteItem.text, quoteOpts, { x: left + padding, y: quoteY });

  // Attribution
  const attrItem = items.find(i => i.role === 'attribution') || { text: 'M. OKAFOR' };
  const attrOpts = {
    fontSize: attrItem.typography?.fontSize || 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.08,
  };
  const attrY = quoteY - 0.25;
  const attrObj = createAndPlace(attrItem.text, attrOpts, { x: left + padding, y: attrY });

  // Caption
  const capItem = items.find(i => i.role === 'caption') || { text: 'COLLECTOR SINCE 2019' };
  const capOpts = {
    fontSize: capItem.typography?.fontSize || 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.12,
  };
  const capY = attrY - 0.25;
  const capObj = createAndPlace(capItem.text, capOpts, { x: left + padding, y: capY });

  // Animation timelines
  const tl = gsap.timeline({ paused: true });
  tl.from(panelMesh.position, {
    y: panelMesh.position.y + 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  tl.to(panelMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);
  // Quote-mark settle
  quoteMarkObj.scale.set(1.04, 1.04, 1.04);
  tl.to(quoteMarkObj.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  }, 0.5);
  tl.play();

  // User data
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    tl.kill();
    panelGeom.dispose();
    panelMat.dispose();
    // Dispose any geometries/textures created by fontAtlas if needed
    [quoteMarkObj, quoteObj, attrObj, capObj].forEach(o => {
      if (o && o.traverse) {
        o.traverse(child => {
          if (child.isMesh) {
            child.geometry?.dispose();
            child.material?.dispose?.();
          }
        });
      }
    });
  };

  return root;
}
